CREATE TABLE `stock` (
  `Id` int NOT NULL AUTO_INCREMENT,
  `product_Id` int NOT NULL DEFAULT '0',
  `Amount` double DEFAULT '0',
  `Created` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `Modified` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`Id`),
  KEY `FK_Stock_Product_Id` (`product_Id`),
  CONSTRAINT `FK_Stock_Product_Id` FOREIGN KEY (`product_Id`) REFERENCES `product` (`Id`) ON DELETE RESTRICT
) ENGINE=InnoDB AUTO_INCREMENT=27 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='Registartie of ordered and received goods. Total of an product_Id gives the total ammount of that product that is available';
